,p_name=>'insert_allowed'
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'a number;',
'U VARCHAR2(45):=V(''APP_USER'');',
'P NUMBER:=:APP_PAGE_ID;',
'begin',
'select 1 into a from user_right t,rights r where upper(t.username)=upper (u)',
'and r.page_no=p and t.insert_allowed=''Y'' and t.right_id=r.right_id;',
