'Select 4 as sort_order,',
'''https://www.google.com/'' as LINK1,',
'''Pending'' title,',
'''250'' data,',
'''fa fa-download fa-fw fa-3x'' as icon_class,',
'''green'' as class1,',
'''green'' as class2,',
'''https://www.google.com/'' as link',
'from dual'))
,p_depending_on_has_to_exist=>true
);
end;
