prompt --application/shared_components/plugins/region_type/com_almalek_dashboard_cards
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(131460242591477595481)
,p_plugin_type=>'REGION TYPE'
,p_name=>'COM.ALMALEK.DASHBOARD_CARDS'
,p_display_name=>'Dashboard Cards (Region Plugin)'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','COM.ALMALEK.DASHBOARD_CARDS'),'')
,p_javascript_file_urls=>'#PLUGIN_FILES#dashboard-cards#MIN#.js'
,p_css_file_urls=>'#PLUGIN_FILES#dashboard-cards#MIN#.css'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'PROCEDURE render_region (',
'  p_plugin IN apex_plugin.t_plugin,',
'  p_region IN apex_plugin.t_region,',
'  p_param  IN apex_plugin.t_region_render_param,',
'  p_result IN OUT NOCOPY apex_plugin.t_region_render_result',
')',
'AS',
'  -- Cursor to execute the region SQL',
'  l_cur         SYS_REFCURSOR;',
'',
'  -- Expected columns (in order)',
'  l_card_id     VARCHAR2(4000);',
'  l_card_value  VARCHAR2(4000);',
'  l_card_label  VARCHAR2(4000);',
'  l_card_icon   VARCHAR2(200);',
'  l_bg_color    VARCHAR2(100);',
'  l_text_color  VARCHAR2(100);',
'  l_link        VARCHAR2(2000);',
'',
'  l_static_id   VARCHAR2(400) := NVL(p_region.static_id, ''dash_'' || p_region.id);',
'  l_counter     PLS_INTEGER := 0;',
'BEGIN',
'  ----------------------------------------------------------------------',
'  -- HTML container start',
'  ----------------------------------------------------------------------',
'  htp.p(''<div id="'' || l_static_id || ''_container" class="dashboard-cards-container">'');',
'  htp.p(''<div class="dashboard-cards-row">'');',
'',
'  ----------------------------------------------------------------------',
'  -- Execute region SQL (the region source must return columns in the expected order)',
'  ----------------------------------------------------------------------',
'  OPEN l_cur FOR p_region.source;',
'',
'  LOOP',
'    FETCH l_cur',
'      INTO l_card_id,',
'           l_card_value,',
'           l_card_label,',
'           l_card_icon,',
'           l_bg_color,',
'           l_text_color,',
'           l_link;',
'',
'    EXIT WHEN l_cur%NOTFOUND;',
'    l_counter := l_counter + 1;',
'',
'    -- Escape values for safe HTML output',
'    l_card_id    := NVL(APEX_ESCAPE.HTML(l_card_id), TO_CHAR(l_counter));',
'    l_card_value := NVL(APEX_ESCAPE.HTML(l_card_value), '''');',
'    l_card_label := NVL(APEX_ESCAPE.HTML(l_card_label), '''');',
'    l_card_icon  := NVL(APEX_ESCAPE.HTML(l_card_icon), ''chart'');',
'    l_bg_color   := NVL(APEX_ESCAPE.HTML(l_bg_color), ''#007BFF'');',
'    l_text_color := NVL(APEX_ESCAPE.HTML(l_text_color), ''#ffffff'');',
'    l_link       := NVL(APEX_ESCAPE.HTML(l_link), '''');',
'',
'    -- Render each card; include data-link only when link is non-empty',
'    htp.p(',
'      ''<div class="dashboard-card" style="background-color:''|| l_bg_color ||',
'      ''; color:''|| l_text_color || ''" '' ||',
'      CASE',
'        WHEN l_link IS NOT NULL AND LENGTH(TRIM(l_link)) > 0 THEN ''data-link="''|| l_link ||''"''',
'        ELSE ''''',
'      END',
'      || ''>''',
'      || ''<i class="fa fa-''|| l_card_icon || ''" aria-hidden="true"></i>''',
'      || ''<div class="card-content">''',
'      ||   ''<div class="card-value">'' || l_card_value || ''</div>''',
'      ||   ''<div class="card-label">'' || l_card_label || ''</div>''',
'      || ''</div>''',
'      || ''</div>''',
'    );',
'  END LOOP;',
'',
'  CLOSE l_cur;',
'',
'  htp.p(''</div></div>'');',
'',
'',
'  ----------------------------------------------------------------------',
'  -- Return render result',
'  ----------------------------------------------------------------------',
'  p_result := apex_plugin.t_region_render_result(',
'    navigable_dom_id => l_static_id || ''_container''',
'  );',
'',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    apex_debug.error(''Dashboard Cards Plugin Error: %s'', SQLERRM);',
'    IF l_cur%ISOPEN THEN',
'      CLOSE l_cur;',
'    END IF;',
'    RAISE;',
'END render_region;',
''))
,p_api_version=>3
,p_render_function=>'render_region'
,p_standard_attributes=>'SOURCE_LOCATION:SUPPORTS_EXTERNAL_FILTERING'
,p_substitute_attributes=>true
,p_version_scn=>15707450831944
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Dashboard Cards (Region Plug-in)',
'',
'This plug-in renders a responsive set of dashboard cards (KPI cards) based on',
'a SQL query defined in the region source. Each row returned by the query is',
'displayed as an individual card.',
'',
'Region Source Requirements:',
'The SQL query must return the following columns in this exact order:',
'',
unistr('1. CARD_ID      \2013 Unique identifier for the card'),
unistr('2. CARD_VALUE   \2013 Main value or number to display'),
unistr('3. CARD_LABEL   \2013 Descriptive label shown under the value'),
unistr('4. CARD_ICON    \2013 Font Awesome icon name (without "fa-")'),
unistr('5. BG_COLOR     \2013 Background color (HEX or valid CSS color)'),
unistr('6. TEXT_COLOR   \2013 Text color (HEX or valid CSS color)'),
unistr('7. LINK         \2013 Optional navigation link (APEX or external URL)'),
'',
'Example SQL:',
'SELECT',
'  ''sales'',',
'  ''125,000'',',
'  ''Total Sales'',',
'  ''shopping-cart'',',
'  ''#3498db'',',
'  ''#ffffff'',',
'  ''f?p=&APP_ID.:2:&SESSION.''',
'FROM dual;',
'',
'Features:',
'- Fully responsive layout (desktop, tablet, mobile)',
'- Supports multiple cards using UNION ALL',
'- Optional clickable cards using navigation links',
'- Separate CSS and JavaScript files for better performance',
'- Smooth entrance animations',
'- Compatible with Oracle APEX 24.x and later',
'',
'Notes:',
'- Do not add a semicolon (;) at the end of the SQL query.',
'- Ensure the number and order of columns are correct.',
'- For best results, disable Lazy Loading on the region.',
'',
'Use Cases:',
'- Dashboards and KPI overviews',
'- Management summary pages',
'- Analytics and monitoring screens'))
,p_version_identifier=>'1.0.0'
,p_about_url=>'https://github.com/malek-al-edresi/apex-dashboard-cards-plugin'
,p_plugin_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Developer Name : Malek Mohammed Al-Edresi',
'Role           : Oracle APEX / PL/SQL Developer',
'Specialization : Oracle APEX Plug-ins, UI Components, Dashboard Design',
'Experience     : Oracle Software Engineer',
'',
'Plug-in Name   : Dashboard Cards (Region Plug-in)',
'Description    : ',
'Reusable and responsive dashboard cards region plug-in for Oracle APEX.',
'Designed to display KPI-style cards using a SQL query source, with support',
'for icons, colors, links, animations, and responsive layouts.',
'',
'Features:',
'- Clean and modern card-based UI',
'- Supports dynamic SQL data sources',
'- Responsive (desktop, tablet, mobile)',
'- Optional navigation links per card',
'- Separate CSS and JavaScript files',
'- Optimized for Oracle APEX 24.x',
'- Ready for Oracle APEX World publication',
'',
'Contact:',
'- Email   : malek.m.edresi@gmail.com',
'- GitHub  : https://github.com/malek-al-edresi',
'- LinkedIn: https://www.linkedin.com/in/malek-al-edresi',
'',
'Copyright:',
unistr('\00A9 2026 Malek Mohammed Al-Edresi'),
'This plug-in is provided for community and educational use.'))
,p_files_version=>25
);
