'INSERT INTO SALE_DETAIL(SALE_ID,PROUDECT_ID,QTY)VALUES(:P24_SALEID,PID,1);',
'ELSE',
'UPDATE SALE_DETAIL SET QTY=QTY+1 WHERE sale_id=:P24_SALEID and proudect_id=pid;',
