'-----sql',
'DECLARE',
'',
'    /* =========================================================',
'       STOCK REPORT',
'       MISBAHULLAH SAMEM SUPER STORE',
'       ========================================================= */',
'',
'    CURSOR c_stock IS',
'        SELECT',
'            s.PROUDECT_ID,',
'            s.PRODUCT_NAME,',
'            s.DETAIL,',
'            s.REORDERQTY,',
'            s.UNIT_ID,',
'            u.UNIT_NAME,',
'            c.COMPANY_NAME,',
'            s.COMPANY_ID,',
'            s.PRICE,',
'            s.PTOTAL,',
'            s.STOTAL,',
'            s.BALANCE',
'        FROM STOCK s inner join companies c on c.company_id=s.company_id  inner join unit u on u.unit_id=s.unit_id',
'        ORDER BY s.PROUDECT_ID;',
'',
'',
'    /* =========================================================',
'       VARIABLES',
'       ========================================================= */',
'',
'    l_html      CLOB;',
'    l_total     NUMBER := 0;',
'    l_row_no    NUMBER := 0;',
'',
'    l_ptotal    NUMBER := 0;',
'    l_stotal    NUMBER := 0;',
'    l_balance   NUMBER := 0;',
'',
'',
'BEGIN',
'',
'    /* =========================================================',
'       TOTAL STOCK RECORDS',
'       ========================================================= */',
'',
'    SELECT COUNT(*)',
'      INTO l_total',
'      FROM STOCK;',
'',
'',
'    /* =========================================================',
'       TOTAL PURCHASE',
'       ========================================================= */',
'',
'    SELECT NVL(SUM(PTOTAL), 0)',
'      INTO l_ptotal',
'      FROM STOCK;',
'',
'',
'    /* =========================================================',
'       TOTAL SALES',
'       ========================================================= */',
'',
'    SELECT NVL(SUM(STOTAL), 0)',
'      INTO l_stotal',
'      FROM STOCK;',
'',
'',
'    /* =========================================================',
'       TOTAL BALANCE',
'       ========================================================= */',
'',
'    SELECT NVL(SUM(BALANCE), 0)',
'      INTO l_balance',
'      FROM STOCK;',
'',
'',
'    /* =========================================================',
'       HTML + CSS',
'       ========================================================= */',
'',
'    l_html := q''[',
'<!DOCTYPE html>',
'<html lang="ps" dir="rtl">',
'',
'<head>',
'',
'<meta charset="UTF-8">',
'',
'<title>',
'Misbahullah Samem Super Store - Stock Report',
'</title>',
'',
'',
'<style>',
'',
'/* =========================================================',
'   GENERAL',
'   ========================================================= */',
'',
'* {',
'    box-sizing: border-box;',
'}',
'',
'html,',
'body {',
'    margin: 0;',
'    padding: 0;',
'    width: 100%;',
'}',
'',
'body {',
'',
'    background: #eeeeee;',
'',
'    color: #000000;',
'',
'    font-family:',
'        Tahoma,',
'        Arial,',
'        sans-serif;',
'',
'}',
'',
'',
'/* =========================================================',
'   REPORT PAGE',
'   ========================================================= */',
'',
'.report-page {',
'',
'    width: 100%;',
'',
'    max-width: 297mm;',
'',
'    min-height: 210mm;',
'',
'    margin: 20px auto;',
'',
'    padding: 12mm;',
'',
'    background: #ffffff;',
'',
'    box-shadow:',
'        0 0 10px',
'        rgba(0,0,0,0.15);',
'',
'}',
'',
'',
'/* =========================================================',
'   BUTTON AREA',
'   ========================================================= */',
'',
'.button-area {',
'',
'    width: 100%;',
'',
'    display: flex;',
'',
'    justify-content: flex-start;',
'',
'    align-items: center;',
'',
'    gap: 10px;',
'',
'    direction: ltr;',
'',
'    margin-bottom: 15px;',
'',
'}',
'',
'',
'/* =========================================================',
'   BUTTONS',
'   ========================================================= */',
'',
'.print-btn,',
'.exit-btn {',
'',
'    border: none;',
'',
'    padding: 10px 24px;',
'',
'    color: #ffffff;',
'',
'    font-family:',
'        Tahoma,',
'        Arial,',
'        sans-serif;',
'',
'    font-size: 14px;',
'',
'    font-weight: bold;',
'',
'    border-radius: 6px;',
'',
'    cursor: pointer;',
'',
'    box-shadow:',
'        0 3px 8px',
'        rgba(0,0,0,0.18);',
'',
'    transition:',
'        all 0.2s ease;',
'',
'}',
'',
'',
'/* =========================================================',
'   PRINT BUTTON',
'   ========================================================= */',
'',
'.print-btn {',
'',
'    background: #1976d2;',
'',
'}',
'',
'.print-btn:hover {',
'',
'    background: #0d5ca8;',
'',
'    transform:',
'        translateY(-1px);',
'',
'}',
'',
'',
'/* =========================================================',
'   EXIT BUTTON',
'   ========================================================= */',
'',
'.exit-btn {',
'',
'    background: #374151;',
'',
'}',
'',
'.exit-btn:hover {',
'',
'    background: #111827;',
'',
'    transform:',
'        translateY(-1px);',
'',
'}',
'',
'',
'/* =========================================================',
'   HEADER',
'   ========================================================= */',
'',
'.report-header {',
'',
'    text-align: center;',
'',
'    border-bottom:',
'        3px solid #1976d2;',
'',
'    padding-bottom: 12px;',
'',
'    margin-bottom: 15px;',
'',
'}',
'',
'',
'.store-name {',
'',
'    font-size: 25px;',
'',
'    font-weight: bold;',
'',
'    margin-bottom: 6px;',
'',
'}',
'',
'',
'.system-name {',
'',
