'',
'}',
'',
'',
'/* =========================================================',
'   SUMMARY CARDS',
'   ========================================================= */',
'',
'.summary-container {',
'',
'    display: grid;',
'',
'    grid-template-columns:',
'        repeat(4, 1fr);',
'',
'    gap: 8px;',
'',
