'',
'    margin-bottom: 5px;',
'',
'}',
'',
'',
'.summary-value {',
'',
'    display: block;',
'',
'    font-size: 17px;',
'',
'    font-weight: bold;',
'',
'}',
'',
'',
'/* =========================================================',
'   STOCK TABLE',
'   ========================================================= */',
'',
'.stock-table {',
'',
'    width: 100%;',
'',
'    border-collapse: collapse;',
'',
'    table-layout: fixed;',
'',
'    font-size: 9px;',
'',
'    color: #000000;',
'',
'}',
'',
'',
'.stock-table th {',
'',
'    border:',
'        1px solid #000000;',
'',
'    background: #e8eef5;',
'',
'    padding: 8px 4px;',
'',
'    text-align: center;',
'',
'    font-weight: bold;',
'',
'    vertical-align: middle;',
'',
'}',
'',
'',
'.stock-table td {',
'',
'    border:',
'        1px solid #000000;',
'',
'    padding: 7px 4px;',
'',
'    text-align: center;',
'',
'    vertical-align: middle;',
'',
'    word-wrap: break-word;',
'',
'    overflow-wrap: anywhere;',
'',
'}',
'',
'',
'/* =========================================================',
'   COLUMN WIDTHS',
'   ========================================================= */',
'',
'.col-no {',
'    width: 4%;',
'}',
'',
'.col-id {',
'    width: 8%;',
'}',
'',
'.col-name {',
'    width: 17%;',
'}',
'',
'.col-detail {',
'    width: 14%;',
'}',
'',
'.col-reorder {',
'    width: 9%;',
'}',
'',
'.col-unit {',
'    width: 7%;',
'}',
'',
'.col-company {',
'    width: 8%;',
'}',
'',
'.col-price {',
'    width: 9%;',
'}',
'',
'.col-ptotal {',
'    width: 9%;',
'}',
'',
'.col-stotal {',
'    width: 8%;',
'}',
'',
'.col-balance {',
'    width: 7%;',
'}',
'',
'',
'/* =========================================================',
'   LTR NUMBERS',
'   ========================================================= */',
'',
'.ltr {',
'',
'    direction: ltr;',
'',
'    text-align: center;',
'',
'}',
'',
'',
'/* =========================================================',
'   BALANCE',
'   ========================================================= */',
'',
'.balance-cell {',
'',
'    font-weight: bold;',
'',
'}',
'',
'',
'/* =========================================================',
'   NO DATA',
'   ========================================================= */',
'',
'.no-data {',
'',
