'',
'}',
'',
'',
'/* =========================================================',
'   SIGNATURES',
'   ========================================================= */',
'',
'.signature-area {',
'',
'    display: flex;',
'',
'    justify-content:',
'        space-between;',
'',
'    margin-top: 35px;',
'',
'    text-align: center;',
'',
'}',
'',
'',
'.signature-box {',
'',
'    width: 28%;',
'',
'}',
'',
'',
'.signature-line {',
'',
'    border-top:',
'        1px solid #000000;',
'',
'    padding-top: 6px;',
'',
