'',
'}',
'',
'',
'/* =========================================================',
'   PRINT',
'   ========================================================= */',
'',
'@media print {',
'',
'    html,',
'    body {',
'',
'        width: 100%;',
'',
'        margin: 0;',
'',
'        padding: 0;',
'',
'        background:',
'            #ffffff !important;',
'',
'        color:',
'            #000000 !important;',
'',
'    }',
'',
'',
'    .report-page {',
'',
'        width: 100%;',
'',
'        max-width: none;',
'',
'        min-height: auto;',
'',
'        margin: 0;',
'',
'        padding: 0;',
'',
'        box-shadow: none;',
'',
'    }',
'',
'',
'    /* Hide buttons when printing */',
'',
'    .button-area {',
'',
'        display:',
'            none !important;',
'',
'    }',
'',
'',
'    .stock-table {',
'',
'        font-size: 8px;',
'',
'    }',
'',
'',
'    .stock-table th,',
'    .stock-table td {',
'',
'        border:',
'            1px solid #000000 !important;',
'',
'        color:',
'            #000000 !important;',
'',
'    }',
'',
'',
'    .stock-table th {',
'',
'        background:',
'            #e8eef5 !important;',
'',
'        -webkit-print-color-adjust:',
'            exact;',
'',
'        print-color-adjust:',
'            exact;',
'',
'    }',
'',
'',
'    .stock-table tr {',
'',
'        page-break-inside:',
'            avoid;',
'',
'        break-inside:',
'            avoid;',
'',
'    }',
'',
'',
'    .stock-table thead {',
'',
'        display:',
'            table-header-group;',
'',
'    }',
'',
'',
'    .report-header {',
'',
'        border-bottom:',
'            2px solid #000000;',
'',
'    }',
'',
'',
'    .report-footer {',
'',
'        page-break-inside:',
'            avoid;',
'',
'    }',
'',
'',
'    @page {',
'',
'        size: A4 landscape;',
'',
'        margin: 10mm;',
'',
'    }',
'',
'}',
'',
'',
'/* =========================================================',
'   MOBILE',
'   ========================================================= */',
'',
'@media screen and',
'       (max-width: 900px) {',
'',
'    .report-page {',
'',
'        margin: 0;',
'',
'        padding: 10px;',
'',
'        overflow-x: auto;',
'',
'    }',
'',
'',
'    .summary-container {',
'',
'        grid-template-columns:',
'            repeat(2, 1fr);',
'',
'    }',
'',
'',
'    .stock-table {',
'',
'        min-width:',
'            1200px;',
'',
'    }',
'',
'}',
'',
'</style>',
'',
'</head>',
'',
'',
'<body>',
'',
'',
'<div class="report-page">',
'',
'',
'<!-- =====================================================',
'     PRINT + EXIT BUTTONS',
'     ===================================================== -->',
'',
'<div class="button-area">',
'',
'',
'    <!-- PRINT -->',
'',
'    <button',
'        type="button"',
'        class="print-btn"',
'        onclick="window.print();">',
'',
unistr('        \D83D\DDA8 Print'),
'',
'    </button>',
'',
'',
'    <!-- EXIT TO HOME PAGE 1 -->',
'',
'    <button',
'        type="button"',
'        class="exit-btn"',
'        onclick="',
'            window.location.href =',
'            ''f?p='' +',
'            $v(''pFlowId'') +',
'            '':1:'' +',
'            $v(''pInstance'');',
'        ">',
'',
unistr('        \2302 Exit'),
'',
'    </button>',
'',
'',
'</div>',
'',
'',
'<!-- =====================================================',
'     REPORT HEADER',
'     ===================================================== -->',
'',
'<div class="report-header">',
'',
'',
'    <div class="store-name">',
'',
unistr('       \062F\0645\0635\0628\0627\062D \0627\0644\0644\0647 \0635\0645\06CC\0645 \0633\0648\067E\0631\0633\067C\0648\0631'),
'    </div>',
'',
'',
'    <div class="system-name">',
'',
unistr('        \0645\062F\06CC\0631\06CC\062A\064A \0645\0639\0644\0648\0645\0627\062A\064A \0633\06CC\0633\062A\0645'),
'',
'    </div>',
'',
'',
'    <div class="report-title">',
'',
unistr('        \062F\0633\067C\0627\06A9/\0630\062E\06CC\0631\06D0 \0631\0627\067E\0648\0631'),
'',
'    </div>',
'',
'',
'    <div class="report-date">',
'',
unistr('        \062F \0631\0627\067E\0648\0631 \0646\06D0\067C\0647:'),
']'';',
'',
'',
'    /* =====================================================',
'       REPORT DATE',
'       ===================================================== */',
'',
'    l_html := l_html ||',
'',
'        TO_CHAR(',
'            SYSDATE,',
'            ''YYYY/MM/DD HH24:MI''',
'        );',
'',
'',
'    l_html := l_html || q''[',
'',
'    </div>',
'',
'',
'</div>',
'',
'',
'<!-- =====================================================',
'     SUMMARY',
'     ===================================================== -->',
'',
'<div class="summary-container">',
'',
'',
'    <!-- TOTAL PRODUCTS -->',
'',
'    <div class="summary-box">',
'',
'        <span class="summary-label">',
'',
unistr('            \067C\0648\0644 \0645\062D\0635\0648\0644\0627\062A'),
'',
'        </span>',
'',
'        <span class="summary-value">',
']'';',
'',
'',
'    l_html := l_html ||',
'',
'        TO_CHAR(l_total);',
'',
'',
'    l_html := l_html || q''[',
'',
'        </span>',
'',
'    </div>',
'',
'',
'    <!-- PURCHASE TOTAL -->',
'',
'    <div class="summary-box">',
'',
'        <span class="summary-label">',
'',
unistr('            \067C\0648\0644 \0627\062E\06CC\0633\062A\0644'),
'',
'        </span>',
'',
'        <span class="summary-value">',
']'';',
'',
'',
'    l_html := l_html ||',
'',
'        TO_CHAR(',
'            l_ptotal,',
'            ''FM999G999G999G990D00''',
'        );',
'',
'',
'    l_html := l_html || q''[',
'',
'        </span>',
'',
'    </div>',
'',
'',
'    <!-- SALES TOTAL -->',
'',
'    <div class="summary-box">',
'',
'        <span class="summary-label">',
'',
unistr('            \067C\0648\0644 \062E\0631\0685\0644\0627\0648'),
'',
'        </span>',
'',
'        <span class="summary-value">',
']'';',
'',
'',
'    l_html := l_html ||',
'',
'        TO_CHAR(',
'            l_stotal,',
'            ''FM999G999G999G990D00''',
'        );',
'',
'',
'    l_html := l_html || q''[',
'',
'        </span>',
'',
'    </div>',
'',
'',
'    <!-- BALANCE -->',
'',
'    <div class="summary-box">',
'',
'        <span class="summary-label">',
'',
unistr('           \0645\0648\062C\0648\062F \062A\0648\06A9\064A'),
'',
'        </span>',
'',
'        <span class="summary-value">',
']'';',
'',
'',
'    l_html := l_html ||',
'',
'        TO_CHAR(',
'            l_balance,',
'            ''FM999G999G999G990D00''',
'        );',
'',
'',
'    l_html := l_html || q''[',
'',
'        </span>',
'',
'    </div>',
'',
'',
'</div>',
'',
'',
'<!-- =====================================================',
'     STOCK TABLE',
'     ===================================================== -->',
'',
'<table class="stock-table">',
'',
'',
'<thead>',
'',
'<tr>',
'',
'',
'    <th class="col-no">',
'',
unistr('        \0634\0645\06D0\0631\0647'),
'',
'    </th>',
'',
'',
'    <th class="col-id">',
'',
unistr('            \062F\062A\0648\06A9\064A \0622\06CC \0689\064A'),
'',
'    </th>',
'',
'',
'    <th class="col-name">',
'',
unistr('        \062F \0645\062D\0635\0648\0644 \0646\0648\0645'),
'',
'    </th>',
'',
'',
'    <th class="col-detail">',
'',
unistr('        \062C\0632\0626\06CC\0627\062A'),
'',
'    </th>',
'',
'',
'    <th class="col-reorder">',
'',
unistr('        \062F \0628\06CC\0627 \0641\0631\0645\0627\06CC\0634 \0645\0642\062F\0627\0631'),
'',
'    </th>',
'',
'',
'    <th class="col-unit">',
'',
unistr('        \0648\0627\062D\062F'),
'',
'    </th>',
'',
'',
'    <th class="col-company">',
'',
unistr('   \06A9\0645\067E\0646\06CD \0646\0648\0645'),
'',
'    </th>',
'',
'',
'    <th class="col-price">',
'',
unistr('        \0642\06CC\0645\062A'),
'',
'    </th>',
'',
'',
'    <th class="col-ptotal">',
'',
unistr('        \0627\062E\06CC\0633\062A\0644'),
'',
'    </th>',
'',
'',
'    <th class="col-stotal">',
'',
unistr('        \062E\0631\0685\0644\0627\0648'),
'',
'    </th>',
'',
'',
'    <th class="col-balance">',
'',
unistr('        \067E\0627\062A\06D0 \062A\0648\06A9\064A'),
'',
'    </th>',
'',
'',
'</tr>',
'',
'</thead>',
'',
'',
'<tbody>',
'',
']'';',
'',
'',
'    /* =====================================================',
'       STOCK CURSOR LOOP',
'       ===================================================== */',
'',
'    FOR r IN c_stock',
'',
'    LOOP',
'',
'        l_row_no :=',
'            l_row_no + 1;',
'',
'',
'        l_html := l_html ||',
'',
'            ''<tr>'' ||',
'',
'',
'            /* NUMBER */',
'',
'            ''<td>'' ||',
'',
'                l_row_no ||',
'',
'            ''</td>'' ||',
'',
'',
'            /* PRODUCT ID */',
'',
'            ''<td class="ltr">'' ||',
'',
'                APEX_ESCAPE.HTML(',
'',
'                    NVL(',
'                        TO_CHAR(',
