wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(5620502772518229)
,p_plug_name=>'Purchase Report'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4501440665235496320
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-----sql',
'DECLARE',
'',
'    /* =========================================================',
'       PURCHASE REPORT',
'       MISBAHULLAH SAMEM SUPER STORE',
'       ',
'       TABLES USED:',
'       PURCHASE',
'       PURCHASE_DETAIL',
'       SUPPLIER',
'       PROUDECT',
'       ========================================================= */',
'',
'',
'    /* =========================================================',
'       PURCHASE HEADER + DETAIL CURSOR',
'       ========================================================= */',
'',
'    CURSOR c_purchase IS',
'',
'        SELECT',
'            p.PURCHASE_ID,',
'            p.SUPPLIER_ID,',
'            s.S_NAME AS SUPPLIER_NAME,',
'            s.F_NAME AS SUPPLIER_FATHER_NAME,',
'            s.CONTACT_NO AS SUPPLIER_PHONE,',
'            p.DATE4,',
'            p.SERIAL_NO,',
'            p.CASH_PAYMENT,',
'',
'            pd.PROUDECT_ID,',
'            pr.PRODUCT_NAME,',
'            pd.QTY,',
'            pd.PPRICE,',
'            pd.SPRICE,',
'            pd.CURRENCY_TYPE',
'',
'        FROM PURCHASE p',
'',
'        LEFT JOIN SUPPLIER s',
'            ON s.SUPPLIER_ID = p.SUPPLIER_ID',
'',
'        LEFT JOIN PURCHASE_DETAIL pd',
'            ON pd.PURCHASE_ID = p.PURCHASE_ID',
'',
'        LEFT JOIN PROUDECT pr',
'            ON pr.PROUDECT_ID = pd.PROUDECT_ID',
'',
'        ORDER BY',
'            p.PURCHASE_ID DESC,',
'            pd.PROUDECT_ID;',
'',
'',
'    /* =========================================================',
'       VARIABLES',
'       ========================================================= */',
'',
'    l_html              CLOB;',
'',
'    l_total_purchase    NUMBER := 0;',
'    l_total_items       NUMBER := 0;',
'    l_total_cash        NUMBER := 0;',
'    l_total_amount      NUMBER := 0;',
'',
'    l_row_no            NUMBER := 0;',
'',
'',
'BEGIN',
'',
'    /* =========================================================',
'       TOTAL PURCHASE TRANSACTIONS',
'       ========================================================= */',
'',
'    SELECT COUNT(*)',
'      INTO l_total_purchase',
'      FROM PURCHASE;',
'',
'',
'    /* =========================================================',
'       TOTAL PURCHASE DETAIL RECORDS',
'       ========================================================= */',
'',
'    SELECT COUNT(*)',
'      INTO l_total_items',
'      FROM PURCHASE_DETAIL;',
'',
'',
'    /* =========================================================',
'       TOTAL CASH PAYMENT',
'       ========================================================= */',
'',
'    SELECT NVL(SUM(CASH_PAYMENT),0)',
'      INTO l_total_cash',
'      FROM PURCHASE;',
'',
'',
'    /* =========================================================',
'       TOTAL PURCHASE AMOUNT',
'       ',
'       PPRICE * QTY',
'       ',
'       QTY is VARCHAR2(20), therefore TO_NUMBER is used.',
'       Invalid/non-numeric QTY is treated as zero.',
'       ========================================================= */',
'',
'    SELECT',
'        NVL(',
'            SUM(',
'                NVL(pd.PPRICE,0) *',
'                CASE',
'                    WHEN REGEXP_LIKE(',
'                        TRIM(pd.QTY),',
'                        ''^[0-9]+([.][0-9]+)?$''',
'                    )',
'                    THEN TO_NUMBER(TRIM(pd.QTY))',
'                    ELSE 0',
'                END',
'            ),',
'            0',
'        )',
'',
'      INTO l_total_amount',
'',
'      FROM PURCHASE_DETAIL pd;',
'',
'',
'    /* =========================================================',
'       HTML START',
'       ========================================================= */',
'',
'    l_html := q''[',
'<!DOCTYPE html>',
'',
'<html lang="ps" dir="rtl">',
'',
'<head>',
'',
'<meta charset="UTF-8">',
'',
'<title>',
'Misbahullah Samem Super Store - Purchase Report',
'</title>',
'',
'',
'<style>',
'',
