'    box-sizing: border-box;',
'}',
'',
'html,',
'body {',
'',
'    margin: 0;',
'',
'    padding: 0;',
'',
'    width: 100%;',
'',
'}',
'',
'',
'body {',
'',
'    background: #eeeeee;',
'',
'    color: #000000;',
'',
'    font-family:',
'        Tahoma,',
'        Arial,',
'        sans-serif;',
'',
'}',
'',
'',
'/* =========================================================',
'   REPORT PAGE',
'   ========================================================= */',
'',
'.report-page {',
'',
