,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*DECLARE',
'    a NUMBER;',
'    CURSOR cr IS SELECT * FROM rights;',
'BEGIN ',
'    FOR i IN cr LOOP',
'        INSERT INTO user_right',
'        VALUES (i.right_id, :P32_UNAME, ''N'', ''N'', ''N'', ''N'');',
'    END LOOP;',
'END;',
'ORA-06503: PL/SQL: Function returned without value*/',
'BEGIN',
'',
'    FOR i IN (',
'        SELECT right_id',
'        FROM rights',
'    ) LOOP',
'',
'        MERGE INTO user_right ur',
'        USING (',
'            SELECT i.right_id AS right_id,',
'                   :P32_UNAME AS username',
'            FROM dual',
'        ) src',
'        ON (',
'            ur.right_id = src.right_id',
'            AND UPPER(ur.username) = UPPER(src.username)',
'        )',
'',
'        WHEN NOT MATCHED THEN',
'            INSERT (',
'                right_id,',
'                username,',
'                select_allowed,',
'                insert_allowed,',
'                update_allowed,',
'                delete_allowed',
'            )',
'            VALUES (',
'                src.right_id,',
'                src.username,',
'                ''N'',',
'                ''N'',',
'                ''N'',',
'                ''N''',
'            );',
'',
'    END LOOP;',
'',
'END;'))
