,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_html         CLOB := '''';',
'    l_total        NUMBER := 0;',
'    l_discount     NUMBER := 0;',
'    l_grand_total  NUMBER := 0;',
'    l_has_customer BOOLEAN := FALSE;',
'',
'    /* ================= CUSTOMER CURSOR ================= */',
'',
'    CURSOR c_customer IS',
'        SELECT',
'            c.customer_id,',
'            c.customer_name,',
'            c.phone,',
'            c.address',
'        FROM customer c',
'        WHERE c.customer_id = :P38_CUSTOMER;',
'',
'',
'    /* ================= SALES CURSOR ================= */',
'',
'    CURSOR c_sales IS',
'        SELECT',
'            s.sale_id,',
'            s.date2,',
'            s.manual_bill_id,',
'            s.bill_discount,',
'',
'            p.proudecT_id,',
'            p.product_name,',
'',
'            sd.qty,',
'            sd.price,',
'            NVL(sd.discount, 0) AS discount,',
'',
'            (',
'                (sd.qty * sd.price)',
'                - NVL(sd.discount, 0)',
'            ) AS line_total',
'',
'        FROM sale s',
'',
'        JOIN sale_detail sd',
'            ON sd.sale_id = s.sale_id',
'',
'        JOIN prouDect p',
'            ON p.proudecT_id = sd.proudecT_id',
'',
'        WHERE s.customer_id = :P38_CUSTOMER',
'',
'        ORDER BY s.date2, s.sale_id, p.product_name;',
'',
'',
'BEGIN',
'',
'    /* =====================================================',
'       CUSTOMER INFORMATION',
'       ===================================================== */',
'',
'    FOR c IN c_customer LOOP',
'',
'        l_has_customer := TRUE;',
'',
'        l_html := l_html || ''',
'',
'        <div class="invoice">',
'',
'            <!-- ================= HEADER ================= -->',
'',
'            <div class="header">',
'',
'                <div class="store-name">',
'                    Misbahullah Samem Super Store',
'                </div>',
'',
'                <div class="system-name">',
'                    Inventory Management System',
'                </div>',
'',
'                <div class="report-title">',
unistr('                    \062F \0645\0634\062A\0631\06CC \062F \062E\0631\0685\0644\0627\0648 \0631\0627\067E\0648\0631'),
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- ================= CUSTOMER ================= -->',
'',
'            <div class="section-title">',
unistr('                \062F \0645\0634\062A\0631\06CC \0645\0639\0644\0648\0645\0627\062A'),
'            </div>',
'',
'            <div class="customer-card">',
'',
'                <div class="info-box">',
'',
'                    <span class="label">',
unistr('                        \062F \0645\0634\062A\0631\06CC \0646\0648\0645'),
'                    </span>',
'',
'                    <span class="value">',
'                        '' || apex_escape.html(c.customer_name) || ''',
'                    </span>',
'',
'                </div>',
'',
'',
'                <div class="info-box">',
'',
'                    <span class="label">',
unistr('                        \062F \062A\0644\06CC\0641\0648\0646 \0634\0645\06D0\0631\0647'),
'                    </span>',
'',
'                    <span class="value">',
'                        '' || apex_escape.html(c.phone) || ''',
'                    </span>',
'',
'                </div>',
'',
'',
'                <div class="info-box">',
'',
'                    <span class="label">',
unistr('                        \067E\062A\0647'),
'                    </span>',
'',
'                    <span class="value">',
'                        '' || apex_escape.html(c.address) || ''',
'                    </span>',
'',
'                </div>',
'',
'',
'                <div class="info-box">',
'',
'                    <span class="label">',
unistr('                        \062F \0631\0627\067E\0648\0631 \0646\06D0\067C\0647'),
'                    </span>',
'',
'                    <span class="value">',
'                        '' || TO_CHAR(SYSDATE, ''YYYY-MM-DD'') || ''',
'                    </span>',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- ================= SALES ================= -->',
'',
'            <div class="section-title sales-title">',
unistr('                \062F \062E\0631\0685\0644\0627\0648 \062A\0641\0635\06CC\0644'),
'            </div>',
'',
'',
'            <table class="sales-table">',
'',
'                <thead>',
'',
'                    <tr>',
'',
'                        <th class="col-no">',
'                            #',
'                        </th>',
'',
'                        <th class="col-id">',
unistr('                            \0645\062D\0635\0648\0644 ID'),
'                        </th>',
'',
'                        <th class="col-product">',
unistr('                            \062F \0645\062D\0635\0648\0644 \0646\0648\0645'),
'                        </th>',
'',
'                        <th class="col-qty">',
unistr('                            \062A\0639\062F\0627\062F'),
'                        </th>',
'',
'                        <th class="col-price">',
unistr('                            \0648\0627\062D\062F \0642\06CC\0645\062A'),
'                        </th>',
'',
'                        <th class="col-discount">',
unistr('                            \062A\062E\0641\06CC\0641'),
'                        </th>',
'',
'                        <th class="col-total">',
unistr('                            \067C\0648\0644'),
'                        </th>',
'',
'                    </tr>',
'',
'                </thead>',
'',
'                <tbody>',
'',
'        '';',
'',
'    END LOOP;',
'',
'',
'    /* =====================================================',
'       SALES DETAILS',
'       ===================================================== */',
'',
'    DECLARE',
'        l_row NUMBER := 0;',
'    BEGIN',
'',
'        FOR r IN c_sales LOOP',
'',
'            l_row := l_row + 1;',
'',
'            l_total :=',
'                l_total',
'                + NVL(r.qty * r.price, 0);',
'',
'            l_discount :=',
'                l_discount',
'                + NVL(r.discount, 0);',
'',
'            l_grand_total :=',
'                l_grand_total',
'                + NVL(r.line_total, 0);',
'',
'',
'            l_html := l_html || ''',
'',
'                    <tr>',
'',
'                        <td class="row-number">',
'                            '' || l_row || ''',
'                        </td>',
'',
'',
'                        <td>',
'                            '' || r.proudecT_id || ''',
'                        </td>',
'',
'',
'                        <td class="product-name">',
'                            '' ||',
'                            apex_escape.html(r.product_name)',
'                            || ''',
'                        </td>',
'',
'',
'                        <td class="qty">',
'                            '' || r.qty || ''',
'                        </td>',
'',
'',
'                        <td class="money">',
'                            '' ||',
'                            TO_CHAR(',
'                                r.price,',
'                                ''FM999G999G999G990D00''',
'                            )',
'                            || ''',
'                        </td>',
'',
'',
'                        <td class="discount">',
'                            '' ||',
'                            TO_CHAR(',
'                                r.discount,',
'                                ''FM999G999G999G990D00''',
'                            )',
'                            || ''',
'                        </td>',
'',
'',
'                        <td class="money total-money">',
'                            '' ||',
'                            TO_CHAR(',
'                                r.line_total,',
'                                ''FM999G999G999G990D00''',
'                            )',
'                            || ''',
'                        </td>',
'',
'                    </tr>',
'',
'            '';',
'',
'        END LOOP;',
'',
'    END;',
'',
'',
'    /* =====================================================',
'       SUMMARY',
'       ===================================================== */',
'',
'    l_html := l_html || ''',
'',
'                </tbody>',
'',
'            </table>',
'',
'',
'            <!-- ================= SUMMARY ================= -->',
'',
'            <div class="summary">',
'',
'                <div class="summary-row">',
'',
'                    <span>',
unistr('                        \067C\0648\0644 \0642\06CC\0645\062A'),
'                    </span>',
'',
'                    <strong>',
'                        '' ||',
'                        TO_CHAR(',
'                            l_total,',
'                            ''FM999G999G999G990D00''',
'                        )',
'                        || ''',
'                    </strong>',
'',
'                </div>',
'',
'',
'                <div class="summary-row discount-row">',
'',
'                    <span>',
unistr('                        \067C\0648\0644 \062A\062E\0641\06CC\0641'),
'                    </span>',
'',
'                    <strong>',
'                        '' ||',
'                        TO_CHAR(',
'                            l_discount,',
'                            ''FM999G999G999G990D00''',
'                        )',
'                        || ''',
'                    </strong>',
'',
'                </div>',
'',
'',
'                <div class="summary-row grand-total">',
'',
'                    <span>',
unistr('                        \0648\0631\0648\0633\062A\06CC \067C\0648\0644 \0642\06CC\0645\062A'),
'                    </span>',
'',
'                    <strong>',
'                        '' ||',
'                        TO_CHAR(',
'                            l_grand_total,',
'                            ''FM999G999G999G990D00''',
'                        )',
'                        || ''',
'                    </strong>',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- ================= FOOTER ================= -->',
'',
'            <div class="footer">',
'',
'                <div class="footer-main">',
unistr('                    \062F \0645\0634\062A\0631\06CC \062F \062E\0631\0685\0644\0627\0648 \0631\0627\067E\0648\0631'),
'                </div>',
'',
'                <div>',
unistr('                    \0645\0646\0646\0647 \0686\06D0 \0632\0645\0648\0696 \062E\062F\0645\062A\0648\0646\0647 \0645\0648 \0627\0646\062A\062E\0627\0628 \06A9\0693\064A'),
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- ================= BUTTONS ================= -->',
'',
'            <div class="buttons">',
'',
'                <button',
'                    type="button"',
'                    onclick="window.print();"',
'                    class="print-btn"',
'                >',
unistr('                    \D83D\DDA8 \0686\0627\067E'),
'                </button>',
'',
'',
'                <button',
'                    type="button"',
'                    onclick="history.back();"',
'                    class="back-btn"',
'                >',
unistr('                    \21A9 \0628\06D0\0631\062A\0647'),
'                </button>',
'',
'            </div>',
'',
'',
'        </div>',
'',
'',
'        <!-- =================================================',
'             PROFESSIONAL CSS',
'        ================================================= -->',
'',
'        <style>',
'',
'        /* ================= PAGE ================= */',
'',
'        @page {',
'',
'            size: A5 portrait;',
'',
'            margin: 7mm;',
'        }',
'',
'',
'        * {',
'',
'            box-sizing: border-box;',
'        }',
'',
'',
'        body {',
'',
'            margin: 0;',
'',
'            padding: 0;',
'',
'            background: #eef2f7;',
'',
'            color: #1f2937;',
'',
'            font-family:',
'                Arial,',
'                Tahoma,',
'                "Noto Sans Arabic",',
'                sans-serif;',
'        }',
'',
'',
'        /* ================= MAIN CARD ================= */',
'',
'        .invoice {',
'',
'            width: 100%;',
'',
'            max-width: 148mm;',
'',
'            margin: 15px auto;',
'',
'            padding: 13px;',
'',
'            background: #ffffff;',
'',
'            direction: rtl;',
'',
'            border-radius: 10px;',
'',
'            border: 1px solid #d9e0e8;',
'',
'            box-shadow:',
'                0 8px 25px rgba(15, 23, 42, 0.10);',
'        }',
'',
'',
'        /* ================= HEADER ================= */',
'',
'        .header {',
'',
'            text-align: center;',
'',
'            padding: 12px 8px 10px;',
'',
'            border-radius: 8px;',
'',
'            background:',
'                linear-gradient(',
'                    135deg,',
'                    #123b5d,',
'                    #176b87',
'                );',
'',
'            color: #ffffff;',
'',
'            margin-bottom: 12px;',
'        }',
'',
'',
'        .store-name {',
'',
'            font-size: 20px;',
'',
'            font-weight: 800;',
'',
'            letter-spacing: .2px;',
'        }',
'',
'',
'        .system-name {',
'',
'            margin-top: 3px;',
'',
'            font-size: 11px;',
'',
'            opacity: .90;',
'        }',
'',
'',
'        .report-title {',
'',
'            margin-top: 8px;',
'',
'            padding-top: 7px;',
'',
'            border-top: 1px solid',
'                rgba(255,255,255,.35);',
'',
'            font-size: 17px;',
'',
'            font-weight: bold;',
'        }',
'',
'',
'        /* ================= SECTION TITLE ================= */',
'',
'        .section-title {',
'',
'            position: relative;',
'',
'            margin: 9px 0 6px;',
'',
'            padding: 6px 9px;',
'',
'            border-right: 4px solid #159a8c;',
'',
'            background: #eaf7f5;',
'',
'            color: #155e5a;',
'',
'            font-size: 12px;',
'',
'            font-weight: 800;',
'',
'            border-radius: 4px;',
'        }',
'',
'',
'        .sales-title {',
'',
'            margin-top: 12px;',
'        }',
'',
'',
'        /* ================= CUSTOMER CARD ================= */',
'',
'        .customer-card {',
'',
'            display: grid;',
'',
'            grid-template-columns:',
'                1fr 1fr;',
'',
'            border: 1px solid #d8dee6;',
'',
'            border-radius: 7px;',
'',
'            overflow: hidden;',
'',
'            background: #ffffff;',
'        }',
'',
'',
'        .info-box {',
'',
'            padding: 7px 8px;',
'',
'            min-height: 42px;',
'',
'            border-bottom: 1px solid #e5e9ef;',
'        }',
'',
'',
'        .info-box:nth-child(odd) {',
'',
'            border-left:',
'                1px solid #e5e9ef;',
'        }',
'',
'',
'        .info-box:nth-child(3),',
'        .info-box:nth-child(4) {',
'',
'            border-bottom: none;',
'        }',
'',
'',
'        .label {',
'',
'            display: block;',
'',
'            color: #64748b;',
'',
'            font-size: 9px;',
'',
'            margin-bottom: 3px;',
'        }',
'',
'',
'        .value {',
'',
'            display: block;',
'',
'            color: #172033;',
'',
'            font-size: 11px;',
'',
'            font-weight: 700;',
'        }',
'',
'',
'        /* ================= TABLE ================= */',
'',
'        .sales-table {',
'',
'            width: 100%;',
'',
'            border-collapse: separate;',
'',
'            border-spacing: 0;',
'',
'            overflow: hidden;',
'',
'            border: 1px solid #cbd5e1;',
'',
'            border-radius: 6px;',
'',
'            font-size: 9px;',
'',
'            table-layout: fixed;',
'        }',
'',
'',
'        .sales-table th {',
'',
'            padding: 6px 2px;',
'',
'            color: #ffffff;',
'',
'            background: #164e63;',
'',
'            border-left: 1px solid',
'                rgba(255,255,255,.25);',
'',
'            text-align: center;',
'',
'            font-weight: 800;',
'        }',
'',
'',
'        .sales-table th:last-child {',
'',
'            border-left: none;',
'        }',
'',
'',
'        .sales-table td {',
'',
'            padding: 5px 2px;',
'',
'            border-left: 1px solid #dbe2ea;',
'',
'            border-top: 1px solid #e2e8f0;',
'',
'            text-align: center;',
'',
'            vertical-align: middle;',
'',
'            word-wrap: break-word;',
'        }',
'',
'',
'        .sales-table td:last-child {',
'',
'            border-left: none;',
'        }',
'',
'',
'        .sales-table tbody tr:nth-child(even) {',
'',
'            background: #f8fafc;',
'        }',
'',
'',
'        .sales-table tbody tr:hover {',
'',
'            background: #edf7f6;',
'        }',
'',
'',
'        .row-number {',
'',
'            font-weight: bold;',
'',
'            color: #64748b;',
'        }',
'',
'',
'        .product-name {',
'',
'            text-align: right !important;',
'',
'            font-weight: 700;',
'',
'            color: #243447;',
'        }',
'',
'',
'        .qty {',
'',
'            font-weight: 700;',
'        }',
'',
'',
'        .money {',
'',
'            direction: ltr;',
'',
'            text-align: center !important;',
'',
'            white-space: nowrap;',
'        }',
'',
'',
'        .discount {',
'',
'            direction: ltr;',
'',
'            text-align: center !important;',
'',
'            color: #b45309;',
'',
'            font-weight: 700;',
'',
'            white-space: nowrap;',
'        }',
'',
'',
'        .total-money {',
'',
'            color: #116149;',
'',
'            font-weight: 800;',
'        }',
'',
'',
'        /* ================= COLUMN WIDTH ================= */',
'',
'        .col-no {',
'            width: 6%;',
'        }',
'',
'',
'        .col-id {',
'            width: 11%;',
'        }',
'',
'',
'        .col-product {',
'            width: 25%;',
'        }',
'',
'',
'        .col-qty {',
'            width: 9%;',
'        }',
'',
'',
'        .col-price {',
'            width: 17%;',
'        }',
'',
'',
'        .col-discount {',
'            width: 14%;',
'        }',
'',
'',
'        .col-total {',
'            width: 18%;',
'        }',
'',
'',
'        /* ================= SUMMARY ================= */',
'',
'        .summary {',
'',
'            margin-top: 10px;',
'',
'            border: 1px solid #cbd5e1;',
'',
'            border-radius: 7px;',
'',
'            overflow: hidden;',
'',
'            background: #ffffff;',
'        }',
'',
'',
'        .summary-row {',
'',
'            display: flex;',
'',
'            justify-content: space-between;',
'',
'            align-items: center;',
'',
'            padding: 7px 10px;',
'',
'            border-bottom: 1px solid #e2e8f0;',
'',
'            font-size: 11px;',
'        }',
'',
'',
'        .summary-row:last-child {',
'',
'            border-bottom: none;',
'        }',
'',
'',
'        .summary-row strong {',
'',
'            direction: ltr;',
'',
'            font-size: 11px;',
'        }',
'',
'',
'        .discount-row {',
'',
'            color: #a16207;',
'',
'            background: #fffbeb;',
'        }',
'',
'',
'        .grand-total {',
'',
'            background: #e8f7f3;',
'',
'            color: #075e54;',
'',
'            font-size: 13px;',
'',
'            font-weight: 800;',
'        }',
'',
'',
'        .grand-total strong {',
'',
'            font-size: 14px;',
'        }',
'',
'',
'        /* ================= FOOTER ================= */',
'',
'        .footer {',
'',
'            margin-top: 12px;',
'',
'            padding: 8px;',
'',
'            text-align: center;',
'',
'            border-top: 1px solid #d5dce5;',
'',
'            color: #64748b;',
'',
'            font-size: 9px;',
'',
'            line-height: 1.8;',
'        }',
'',
'',
'        .footer-main {',
'',
'            color: #164e63;',
'',
'            font-weight: 800;',
'',
'            font-size: 10px;',
'        }',
'',
'',
'        /* ================= BUTTONS ================= */',
'',
'        .buttons {',
'',
'            display: flex;',
'',
'            justify-content: center;',
'',
'            gap: 7px;',
'',
'            margin-top: 10px;',
'        }',
'',
'',
'        .buttons button {',
'',
'            border: none;',
'',
'            border-radius: 5px;',
'',
'            padding: 7px 18px;',
'',
'            font-family: inherit;',
'',
'            font-size: 11px;',
'',
'            font-weight: 700;',
'',
'            cursor: pointer;',
'',
'            transition: .2s;',
'        }',
'',
'',
'        .print-btn {',
'',
'            background: #176b87;',
'',
'            color: #ffffff;',
'',
'            box-shadow:',
'                0 3px 8px',
'                rgba(23,107,135,.25);',
'        }',
'',
'',
'        .back-btn {',
'',
'            background: #64748b;',
'',
'            color: #ffffff;',
'',
'            box-shadow:',
'                0 3px 8px',
'                rgba(100,116,139,.20);',
'        }',
'',
'',
'        .buttons button:hover {',
'',
'            transform: translateY(-1px);',
'',
'            opacity: .92;',
'        }',
'',
'',
'        /* ================= PRINT ================= */',
'',
'        @media print {',
'',
'            body {',
'',
'                background: #ffffff;',
'            }',
'',
'',
'            .invoice {',
'',
'                width: 100%;',
'',
'                max-width: none;',
'',
'                margin: 0;',
'',
'                padding: 0;',
'',
'                border: none;',
'',
'                box-shadow: none;',
'',
'                border-radius: 0;',
'            }',
'',
'',
'            .buttons {',
'',
'                display: none !important;',
'            }',
'',
'',
'            .header {',
'',
'                print-color-adjust: exact;',
'',
'                -webkit-print-color-adjust: exact;',
'            }',
'',
'',
'            .sales-table th {',
'',
'                print-color-adjust: exact;',
'',
'                -webkit-print-color-adjust: exact;',
'            }',
'',
'',
'            .discount-row,',
'            .grand-total {',
'',
'                print-color-adjust: exact;',
'',
