'',
'    '';',
'',
'',
'    /* =====================================================',
'       CUSTOMER NOT FOUND',
'       ===================================================== */',
'',
'    IF NOT l_has_customer THEN',
'',
'        RETURN ''',
'',
'        <div style="',
'            direction:rtl;',
'            text-align:center;',
'            margin:40px auto;',
'            padding:25px;',
