unistr('                \0645\0634\062A\0631\06CC \067E\06CC\062F\0627 \0646\0634\0648'),
'            </h3>',
'',
'            <p>',
unistr('                \0645\0647\0631\0628\0627\0646\064A \0648\06A9\0693\0626 \062F \0645\0634\062A\0631\06CC ID \0648\06AB\0648\0631\0626.'),
'            </p>',
'',
'        </div>'';',
'',
'    END IF;',
'',
'',
'    RETURN l_html;',
'',
'',
'EXCEPTION',
'',
'    WHEN OTHERS THEN',
'',
'        RETURN ''',
'',
'        <div style="',
'            direction:ltr;',
'            color:#b91c1c;',
'            background:#fff;',
'            padding:20px;',
'            border:1px solid #ef4444;',
'            border-radius:6px;',
'            font-family:Arial;',
