,p_validation_name=>'Check Password Match'
,p_validation_sequence=>10
,p_validation=>':P41_NEW_PASSWORD = :P41_CONFIRM_PASSWORD'
,p_validation2=>'PLSQL'
,p_validation_type=>'EXPRESSION'
,p_error_message=>'New password and confirmation password do not match.'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4904749440304709)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CHANGE_POSSWORD_PROCESS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_count        NUMBER;',
'    l_current_hash VARCHAR2(32);',
'BEGIN',
'',
'    -- Check current password',
'    l_current_hash := RAWTOHEX(',
'        DBMS_CRYPTO.HASH(',
'            UTL_RAW.CAST_TO_RAW(:P41_CURRENT_PASSWORD),',
'            DBMS_CRYPTO.HASH_MD5',
'        )',
'    );',
'',
'    SELECT COUNT(*)',
'      INTO l_count',
'      FROM login',
'     WHERE UPPER(username) = UPPER(:APP_USER)',
'       AND userpassword = l_current_hash',
'       AND status = ''Active'';',
'',
'    IF l_count = 0 THEN',
'        raise_application_error(',
'            -20001,',
'            ''Current password is incorrect.''',
'        );',
'    END IF;',
'',
'    -- Update password',
'    -- USER_PASS_TRG will hash the new password',
'    UPDATE login',
'       SET userpassword = :P41_NEW_PASSWORD',
'     WHERE UPPER(username) = UPPER(:APP_USER)',
'       AND status = ''Active'';',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        raise_application_error(',
'            -20002,',
'            ''User account was not found.''',
'        );',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(4904593138304707)
,p_process_success_message=>'Password changed successfully.'
,p_internal_uid=>4904749440304709
);
end;
